    \"Check Point agent intelligence service (Version 1.2429.961498) install package\" \\
    \"\" \\
    \"1.2429.961498\" \\
    \"./install-agent-intelligence-service.sh\""
	if test x"$script" != x; then
	    echo Script run after extraction:
	    echo "    " $script $scriptargs
	fi
