	    MS_dd "$0" $offset $s | eval "gzip -cd" | UnTAR t
	    offset=`expr $offset + $s`
	done
	exit 0
	;;
    --tar)
	offset=`head -n 603 "$0" | wc -c | tr -d " "`
	arg1="$2"
    if ! shift 2; then MS_Help; exit 1; fi
	for s in $filesizes
	do
	    MS_dd "$0" $offset $s | eval "gzip -cd" | tar "$arg1" - "$@"
	    offset=`expr $offset + $s`
	done
	exit 0
	;;
    --check)
	MS_Check "$0" y
	exit 0
	;;
    --confirm)
	verbose=y
	shift
	;;
    --noexec)
	script=""
	shift
	;;
    --keep)
	keep=y
	shift
	;;
    --install)
	scriptargs="./install-agent-intelligence-service.sh --install"
	shift
	break ;;
    --force)
	scriptargs="./install-agent-intelligence-service.sh --force"
	shift
	;;
    --uninstall)
	scriptargs="./install-agent-intelligence-service.sh --uninstall"
	shift
	;;
    --pre_install_test)
	scriptargs="./install-agent-intelligence-service.sh --pre_install_test"
	shift
	;;
    --post_install_test)
	scriptargs="./install-agent-intelligence-service.sh --post_install_test"
	shift
	;;
    --version)
	MS_Printf "$package_version\n" 2>&1
	exit 0
